import { chromium } from 'playwright';
import fs from 'node:fs';

const badge = (rx) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="512" height="512">
<defs><linearGradient id="b" x1="0" y1="0" x2="32" y2="32" gradientUnits="userSpaceOnUse">
<stop offset="0" stop-color="#8b5cf6"/><stop offset="1" stop-color="#d946ef"/></linearGradient></defs>
<rect width="32" height="32" rx="${rx}" fill="url(#b)"/>
<g fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">
<path d="M6.5 23.5 11 9 16 19.5 21 9 25.5 23.5"/></g></svg>`;

const b = await chromium.launch();
const shoot = async (svg, size, out) => {
  const p = await b.newPage({ viewport: { width: size, height: size }, deviceScaleFactor: 1 });
  await p.setContent(`<body style="margin:0">${svg.replace(/width="512" height="512"/, `width="${size}" height="${size}"`)}</body>`);
  await p.waitForTimeout(200);
  await p.screenshot({ path: out, omitBackground: false });
  await p.close();
};
await shoot(badge(0), 180, 'app/apple-icon.png');       // iOS masks its own corners
await shoot(badge(7.5), 32, '/tmp/fav32.png');
await b.close();

// Pack the 32x32 PNG into an ICO container. Browsers and crawlers still fetch
// /favicon.ico by path, and PNG-in-ICO has been supported since Vista.
const png = fs.readFileSync('/tmp/fav32.png');
const head = Buffer.alloc(22);
head.writeUInt16LE(0, 0); head.writeUInt16LE(1, 2); head.writeUInt16LE(1, 4);
head.writeUInt8(32, 6); head.writeUInt8(32, 7); head.writeUInt8(0, 8); head.writeUInt8(0, 9);
head.writeUInt16LE(1, 10); head.writeUInt16LE(32, 12);
head.writeUInt32LE(png.length, 14); head.writeUInt32LE(22, 18);
fs.writeFileSync('app/favicon.ico', Buffer.concat([head, png]));
console.log('apple-icon', fs.statSync('app/apple-icon.png').size, 'favicon.ico', fs.statSync('app/favicon.ico').size);
EOF
